mapper.select:
SELECT user_id, user_email, user_name, user_phone, joined_at
FROM teampack.users
WHERE user_email = #{email}

mapper.update:
UPDATE teampack.users
SET user_name = #{userName},
    user_phone = #{userPhone}
WHERE user_id = #{userId}

UPDATE teampack.users
SET user_password = #{newPassword}
WHERE user_id = #{userId}
